CREATE FUNCTION `clean_path`(_path VARCHAR(1024)
) RETURNS varchar(1024) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    DETERMINISTIC
BEGIN
  DECLARE _r VARCHAR(1024);
  SELECT REGEXP_REPLACE(_path, '/+', '/') INTO _r;
  SELECT REGEXP_REPLACE(_r, '\<.*\>', '') INTO _r;
  RETURN _r;
END ;;
DELIMITER ;
