CREATE FUNCTION `media_unseen`(_metadata JSON,
  _uid VARCHAR(16)
) RETURNS int(11)
    DETERMINISTIC
BEGIN
  DECLARE _res INTEGER DEFAULT 0;
  SELECT 
    IF(JSON_EXISTS(_metadata, "$._seen_") AND NOT JSON_EXISTS(_metadata, CONCAT("$._seen_.", _uid)), 1, 0) INTO _res;
  RETURN _res;
END ;;
