CREATE PROCEDURE `acl_revoke`(
  IN _rid VARCHAR(16),
  IN _eid VARCHAR(16)
)
BEGIN

  IF _eid != '' THEN
    DELETE FROM acl WHERE resource_id=_rid AND entity_id=_eid;
  ELSE
    DELETE FROM acl WHERE resource_id=_rid;
  END IF;

END ;;
