CREATE PROCEDURE `block_delete_by_lang`(
   IN _locale       VARCHAR(100)
)
BEGIN
  DELETE FROM block_history WHERE lang=_locale;
  DELETE block FROM block WHERE id NOT IN (SELECT master_id FROM block_history);
END ;;
