CREATE PROCEDURE `conference_start`(
  IN _uid VARCHAR(16)
)
BEGIN
  DECLARE _status VARCHAR(255);
  SELECT IF(permission & 0b0010000, 'started', 'waiting')
    FROM permission 
    WHERE resource_id='*' AND entity_id=_uid INTO _status;

  UPDATE conference SET `status`=_status;
END ;;
