CREATE PROCEDURE `dmz_sync_grant`(
  IN _resource_id VARCHAR(50)
)
BEGIN
  DECLARE _owner_id VARCHAR(50); 

  DELETE FROM  yp.dmz_token  WHERE node_id = _resource_id
  AND guest_id  NOT IN (
  SELECT  entity_id FROM permission WHERE resource_id = _resource_id );

END ;;
