CREATE PROCEDURE `file_version_delete_old`(
  IN _nid VARCHAR(16)
  
)
BEGIN
  DELETE FROM file_version
  WHERE is_active = 0
    AND (_nid IS NULL OR nid = _nid);

  SELECT ROW_COUNT() AS deleted;
END ;;
