CREATE PROCEDURE `folder_revoke_otl`(
  IN _nid VARCHAR(16) CHARACTER SET ascii
)
BEGIN
  
  
  
  UPDATE media
  SET metadata = JSON_MERGE_PATCH(
        IFNULL(metadata, '{}'),
        '{"fperm":{"one_time":0,"one_time_url":null}}'
      )
  WHERE id = _nid;
END ;;
