CREATE PROCEDURE `folder_save_permissions`(
  IN _nid    VARCHAR(16) CHARACTER SET ascii,
  IN _config TEXT
)
BEGIN
  
  
  
  
  
  
  
  
  
  

  DECLARE _patch TEXT;

  SET _patch = CONCAT('{"fperm":', _config, '}');

  UPDATE media
  SET metadata = JSON_MERGE_PATCH(IFNULL(metadata, '{}'), _patch)
  WHERE id = _nid;

  SELECT 'OK' AS status, _nid AS nid;
END ;;
