CREATE PROCEDURE `hub_count_admins`()
BEGIN
  
  
  
  
  SELECT COUNT(DISTINCT p.entity_id) AS total
  FROM permission p
  WHERE p.resource_id = '*'
    AND (p.permission & 16) > 0;
END ;;
