CREATE PROCEDURE `hub_get_member_with_push_token`()
BEGIN
  SELECT  
    d.id,
    d.email,
    dr.push_token,
    dr.device_id
    FROM permission p 
    INNER JOIN yp.drumate d on p.entity_id = d.id
    INNER JOIN yp.device_registation dr on d.id = dr.uid
    WHERE resource_id="*";
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
