CREATE PROCEDURE `hub_get_workspace_admins`()
BEGIN
  SELECT DISTINCT entity_id
  FROM permission
  WHERE resource_id = '*'
    AND permission = 31
    AND (expiry_time = 0 OR expiry_time > UNIX_TIMESTAMP());
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
