CREATE PROCEDURE `layout_backup`(
   IN _id           VARBINARY(16),
   IN _letc  MEDIUMTEXT
)
BEGIN
   UPDATE layout SET backup=_letc, mtime=UNIX_TIMESTAMP() WHERE id=_id;
   SELECT backup, id FROM layout WHERE id=_id;
END ;;
