CREATE PROCEDURE `mfs_empty_bin`(
)
BEGIN

  DECLARE _count INT(6);
  SELECT count(*) FROM media WHERE status='deleted' INTO _count;
  DELETE FROM media WHERE status='deleted' AND id=_id;
  SELECT _count AS count;
END ;;
