CREATE PROCEDURE `mfs_parent_node_attr`(
  IN _node_id VARCHAR(16)
)
BEGIN
  DECLARE _parent_id VARCHAR(16);
  SELECT parent_id FROM media WHERE id=_node_id INTO _parent_id;
  CALL mfs_node_attr(_parent_id);
END ;;
