/*!50003 DROP PROCEDURE IF EXISTS `mfs_restore` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_restore`(
  IN _id VARCHAR(16)
)
BEGIN
  DECLARE _category VARCHAR(40);
  DECLARE _old_node_path VARCHAR(6000);
  DECLARE _new_node_path VARCHAR(6000);
  DECLARE _parent_id VARCHAR(16);
  DECLARE _home_id VARCHAR(16);
  DECLARE _hub_id VARCHAR(16);
  DECLARE _total_filesize BIGINT DEFAULT 0;
  DECLARE _parent_exists INT DEFAULT 0;
  DECLARE _restored_filename VARCHAR(128);
  DECLARE _extension VARCHAR(100);

  
  SELECT id INTO _home_id
  FROM media WHERE (parent_id IS NULL OR parent_id = '' OR parent_id = '0');

  SELECT id INTO _hub_id
  FROM yp.entity WHERE db_name = database();

  IF _id IS NULL OR _id = _home_id THEN
    SELECT 1 AS failed, 0 AS parent_missing, 'Could not restore root itself' AS message;
  ELSE
    
    SELECT category, parent_id, user_filename, extension
    INTO _category, _parent_id, _restored_filename, _extension
    FROM trash_media WHERE id = _id;

    
    SELECT COUNT(*) INTO _parent_exists
    FROM media WHERE id = _parent_id;

    IF _parent_exists = 0 THEN
      
      SELECT 0 AS failed, 1 AS parent_missing, _parent_id AS original_parent_id, _id AS nid;
    ELSE
      
      SET _restored_filename = unique_filename(_parent_id, _restored_filename, COALESCE(_extension, ''));

      START TRANSACTION;

      
      IF _category = 'folder' THEN
        SELECT CONCAT(parent_path, user_filename) INTO _old_node_path
        FROM trash_media WHERE id = _id;
      END IF;

      
      INSERT INTO media (
        sys_id, id, origin_id, owner_id, host_id,
        file_path, user_filename, parent_id, parent_path,
        extension, mimetype, category, isalink, filesize,
        geometry, publish_time, upload_time,
        last_download, download_count, metadata, caption,
        status, approval, rank
      )
      SELECT
        sys_id, id, origin_id, owner_id, host_id,
        file_path, _restored_filename, parent_id, parent_path,
        extension, mimetype, category, isalink, filesize,
        geometry, publish_time, upload_time,
        last_download, download_count, metadata, caption,
        'active', approval, rank
      FROM trash_media WHERE id = _id;

      
      
      IF _category = 'folder' THEN
        INSERT INTO media (
          sys_id, id, origin_id, owner_id, host_id,
          file_path, user_filename, parent_id, parent_path,
          extension, mimetype, category, isalink, filesize,
          geometry, publish_time, upload_time,
          last_download, download_count, metadata, caption,
          status, approval, rank
        )
        SELECT
          sys_id, id, origin_id, owner_id, host_id,
          file_path, user_filename, parent_id, parent_path,
          extension, mimetype, category, isalink, filesize,
          geometry, publish_time, upload_time,
          last_download, download_count, metadata, caption,
          'active', approval, rank
        FROM trash_media
        WHERE CONCAT(parent_path, user_filename) LIKE CONCAT(_old_node_path, '/%');

        SELECT COALESCE(SUM(filesize), 0) INTO _total_filesize
        FROM trash_media
        WHERE id = _id
          OR CONCAT(parent_path, user_filename) LIKE CONCAT(_old_node_path, '/%');
      ELSE
        SELECT filesize INTO _total_filesize
        FROM trash_media WHERE id = _id;
      END IF;

      
      UPDATE media
      SET parent_path = parent_path(id),
          file_path = clean_path(CONCAT(parent_path(id), '/', user_filename, '.', extension))
      WHERE id = _id;

      
      IF _category = 'folder' THEN
        SELECT CONCAT(parent_path(id), user_filename) INTO _new_node_path
        FROM media WHERE id = _id;

        UPDATE media
        SET parent_path = parent_path(id),
            file_path = clean_path(CONCAT(parent_path(id), '/', user_filename, '.', extension))
        WHERE CONCAT(parent_path, user_filename) LIKE CONCAT(_new_node_path, '/%');
      END IF;

      
      IF _hub_id IS NOT NULL AND _total_filesize > 0 THEN
        UPDATE yp.disk_usage
        SET size = IFNULL(size, 0) + _total_filesize
        WHERE hub_id = _hub_id;
      END IF;

      
      IF _category = 'folder' THEN
        DELETE FROM trash_media
        WHERE id = _id
          OR CONCAT(parent_path, user_filename) LIKE CONCAT(_old_node_path, '/%');
      ELSE
        DELETE FROM trash_media WHERE id = _id;
      END IF;

      COMMIT;

      
      SELECT * FROM media WHERE id = _id;
    END IF;
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `mfs_restore_into_next` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_restore_into_next`(
  IN _nodes JSON,
  IN _uid VARCHAR(16) CHARACTER SET ascii 
)
BEGIN

  DECLARE _idx INT(4) DEFAULT 0; 
  DECLARE _nid VARCHAR(16) CHARACTER SET ascii;
  DECLARE _dest_id VARCHAR(16) CHARACTER SET ascii;
  DECLARE _recipient_id VARCHAR(16);
  DECLARE _shub_id VARCHAR(16) CHARACTER SET ascii;
  DECLARE _shub_db VARCHAR(40);
  DECLARE _dhub_id VARCHAR(16) CHARACTER SET ascii;
  DECLARE _dhub_db VARCHAR(40);
  DECLARE _dhome_dir VARCHAR(512) DEFAULT null;
  DECLARE _shome_dir VARCHAR(512) DEFAULT null;
  DECLARE _rows_affected INT DEFAULT 0;

  DECLARE exit handler for sqlexception
  BEGIN
    GET DIAGNOSTICS CONDITION 1
      @sqlstate = RETURNED_SQLSTATE, 
      @errno = MYSQL_ERRNO, 
      @text = MESSAGE_TEXT;
    
    INSERT IGNORE INTO _restore_debug (step, details, error_state, error_msg) 
    VALUES ('EXCEPTION', 'SQL Exception caught', @sqlstate, CONCAT('Error ', @errno, ': ', @text));
    
    ROLLBACK;
    SELECT * FROM _restore_debug ORDER BY ts;
  END;

  
  DROP TABLE IF EXISTS _restore_debug;
  CREATE TEMPORARY TABLE _restore_debug (
    step VARCHAR(100),
    details TEXT,
    error_state VARCHAR(10) DEFAULT NULL,
    error_msg TEXT DEFAULT NULL,
    ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
  );

  INSERT INTO _restore_debug (step, details) 
  VALUES ('START', CONCAT('nodes=', _nodes, ', uid=', _uid));

  START TRANSACTION;

  DROP TABLE IF EXISTS _mytree; 
  CREATE TEMPORARY TABLE _mytree (
    id varchar(16) CHARACTER SET ascii DEFAULT NULL,
    parent_id varchar(16) CHARACTER SET ascii DEFAULT NULL,
    user_filename varchar(128) DEFAULT NULL,
    extension varchar(100) CHARACTER SET ascii DEFAULT NULL,
    category varchar(16) NOT NULL DEFAULT 'other',
    flag  TINYINT default 0,
    shub_id varchar(16) CHARACTER SET ascii DEFAULT NULL,
    dhub_id varchar(16) CHARACTER SET ascii DEFAULT NULL,
    shome_dir VARCHAR(512) DEFAULT null,
    dhome_dir VARCHAR(512) DEFAULT null,
    shub_db VARCHAR(40),
    dhub_db VARCHAR(40),
    is_show INT DEFAULT 0,
    nid varchar(16) CHARACTER SET ascii DEFAULT NULL
  );
  
  DROP TABLE IF EXISTS _disk_usage_restores;
  CREATE TEMPORARY TABLE _disk_usage_restores (
    hub_id varchar(16) CHARACTER SET ascii NOT NULL,
    delta bigint DEFAULT 0,
    PRIMARY KEY (hub_id)
  );

  WHILE _idx < JSON_LENGTH(_nodes) DO 
    SELECT JSON_UNQUOTE(JSON_EXTRACT(_nodes, CONCAT("$[", _idx, "]"))) INTO @_node;
    SELECT JSON_VALUE(@_node, "$.nid") INTO _nid;
    SELECT JSON_VALUE(@_node, "$.hub_id") INTO _shub_id;
    SELECT JSON_VALUE(@_node, "$.pid") INTO _dest_id;
    SELECT JSON_VALUE(@_node, "$.recipient_id") INTO _dhub_id;
    
    SELECT db_name,home_dir FROM yp.entity WHERE id = _shub_id INTO _shub_db,_shome_dir; 
    SELECT db_name,home_dir FROM yp.entity WHERE id = _dhub_id INTO _dhub_db,_dhome_dir; 

    
    SET @st = CONCAT(
      "INSERT INTO _mytree (id,parent_id,user_filename,extension,category,flag,nid)
       WITH RECURSIVE mytree AS 
      (
        SELECT id, ",QUOTE(_dest_id), " parent_id ,user_filename, extension,category,0 flag,", QUOTE(_nid ) ," nid   
        FROM  ",_shub_db,".trash_media WHERE id = ", QUOTE(_nid) , "
          UNION ALL
        SELECT m.id, m.parent_id ,m.user_filename, m.extension,m.category ,0 ,", QUOTE(_nid)," 
        FROM ",_shub_db,".trash_media AS m JOIN mytree AS t ON m.parent_id = t.id
      )
      SELECT id,parent_id,user_filename,extension,category,flag,nid FROM mytree;"
    );
    PREPARE stmt FROM @st;
    EXECUTE stmt ;
    DEALLOCATE PREPARE stmt; 

    
    SET @st = CONCAT(
    "UPDATE _mytree m
    INNER JOIN ",_dhub_db,".media t  ON t.parent_id = m.parent_id 
          AND t.user_filename = m.user_filename 
          AND t.extension = m.extension
          AND m.nid =",QUOTE(_nid),"
    SET m.flag = 1;"
    );
    PREPARE stmt FROM @st;
    EXECUTE stmt ;
    DEALLOCATE PREPARE stmt;

    
    SET @st = CONCAT(
    "INSERT INTO ",_dhub_db,".media 
        (sys_id,id,origin_id,owner_id,host_id,file_path,user_filename,parent_id,parent_path,extension,mimetype,
        category,isalink,filesize,geometry,publish_time,upload_time,last_download,download_count,
        metadata,caption,status,approval,rank)
    SELECT 
        NULL,m.id,m.origin_id,m.owner_id,m.host_id,NULL, m.user_filename ,s.parent_id,'',m.extension,m.mimetype,
        m.category,m.isalink,m.filesize,m.geometry,m.publish_time,m.upload_time,m.last_download,m.download_count,
        m.metadata,m.caption,'active',m.approval,m.rank
    FROM ",_shub_db,".trash_media m 
    INNER JOIN _mytree s ON s.id = m.id
    WHERE s.flag =0  AND s.nid =",QUOTE(_nid),";"
    );
    PREPARE stmt FROM @st;
    EXECUTE stmt ;
    DEALLOCATE PREPARE stmt;

    
    SET @st = CONCAT(
      "INSERT INTO ",_dhub_db,".media (sys_id,id,origin_id,owner_id,host_id,file_path,user_filename,parent_id,parent_path,extension,mimetype,
          category,isalink,filesize,geometry,publish_time,upload_time,last_download,download_count,
          metadata,caption,status,approval,rank)
      SELECT NULL,m.id,m.origin_id,m.owner_id,m.host_id,NULL, ",_dhub_db,".unique_filename(s.parent_id, m.user_filename, m.extension) ,s.parent_id,'',m.extension,m.mimetype,
          m.category,m.isalink,m.filesize,m.geometry,m.publish_time,m.upload_time,m.last_download,m.download_count,
          m.metadata,m.caption,'active',m.approval,m.rank
      FROM ",_shub_db,".trash_media m 
      INNER JOIN _mytree s ON s.id = m.id
      WHERE flag =1 AND s.nid =",QUOTE(_nid),";"
      );
    PREPARE stmt FROM @st;
    EXECUTE stmt ;
    DEALLOCATE PREPARE stmt;

    
    SET @st = CONCAT("UPDATE ", _dhub_db, 
          ".media SET parent_path=",_dhub_db,".parent_path(id) WHERE id IN (SELECT id FROM _mytree  WHERE nid =",QUOTE(_nid) ,");"
        );
    PREPARE stmt FROM @st;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

    SET @st = CONCAT("UPDATE ", _dhub_db, 
          ".media SET file_path =clean_path(concat(parent_path, '/', user_filename, '.', extension)) WHERE id IN (SELECT id FROM _mytree  WHERE nid =", QUOTE(_nid),");"
        );
    PREPARE stmt FROM @st;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

    
    SET @total_size = 0;
    SET @st = CONCAT("SELECT IFNULL(SUM(filesize),0) FROM ", _shub_db, ".trash_media WHERE id IN (SELECT id FROM _mytree WHERE nid =", QUOTE(_nid),") INTO @total_size");
    PREPARE stmt FROM @st;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
    
    INSERT INTO _disk_usage_restores (hub_id, delta)
    VALUES (_shub_id, -@total_size)
    ON DUPLICATE KEY UPDATE delta = delta - @total_size;
    
    INSERT INTO _disk_usage_restores (hub_id, delta)
    VALUES (_dhub_id, @total_size)
    ON DUPLICATE KEY UPDATE delta = delta + @total_size;

    
    SET @st = CONCAT(
    "DELETE FROM ",_shub_db,".trash_media WHERE id IN (SELECT id FROM _mytree  WHERE nid =", QUOTE(_nid) ,");"
    );
    PREPARE stmt FROM @st;
    EXECUTE stmt ;
    DEALLOCATE PREPARE stmt;

    UPDATE  _mytree SET is_show = 1  WHERE id =_nid;
    DELETE FROM _mytree WHERE category IN ("hub") AND is_show =0;
    
    SELECT NULL,NULL INTO _dhub_db ,_shub_db;
    SELECT _idx + 1 INTO _idx;
  END WHILE; 

  
  BEGIN
    DECLARE _finished INT DEFAULT 0;
    DECLARE _update_hub_id VARCHAR(16);
    DECLARE _update_delta BIGINT;
    
    DECLARE update_cursor CURSOR FOR 
      SELECT hub_id, delta FROM _disk_usage_restores;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET _finished = 1;
    DECLARE CONTINUE HANDLER FOR 1264 BEGIN END; 
    
    OPEN update_cursor;
    update_loop: LOOP
      FETCH update_cursor INTO _update_hub_id, _update_delta;
      IF _finished = 1 THEN LEAVE update_loop; END IF;
      
      IF _update_delta < 0 THEN
         UPDATE yp.disk_usage 
         SET size = IF(IFNULL(size, 0) < ABS(_update_delta), 0, IFNULL(size, 0) - ABS(_update_delta))
         WHERE hub_id = _update_hub_id;
      ELSE
         UPDATE yp.disk_usage 
         SET size = IFNULL(size, 0) + _update_delta
         WHERE hub_id = _update_hub_id;
      END IF;
    END LOOP;
    CLOSE update_cursor;
  END;

  COMMIT;

  
  SELECT 
      id nid,  
      CONCAT(TRIM(TRAILING '/' FROM _shome_dir), "/__storage__/") src_mfs_root,  
      id des_id, 
      CONCAT(TRIM(TRAILING '/' FROM _dhome_dir), "/__storage__/") des_mfs_root,
      dhub_id dest_hub_id, 
      dhub_db dest_db_name, 
      'move' `action`
  FROM _mytree WHERE category NOT IN ("folder","hub") 
    UNION ALL
  SELECT 
      id nid,  
      CONCAT(TRIM(TRAILING '/' FROM _shome_dir), "/__storage__/") src_mfs_root,  
      id des_id, 
      CONCAT(TRIM(TRAILING '/' FROM _dhome_dir), "/__storage__/") des_mfs_root,
      dhub_id dest_hub_id, 
      dhub_db dest_db_name, 
      'show' `action`
  FROM _mytree WHERE is_show = 1; 

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `mfs_root_conflict_files` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_root_conflict_files`(
  IN _src_ids VARCHAR(5000),
  IN _dest_pids VARCHAR(5000),
  IN _des_entity_id VARCHAR(16)
  )
BEGIN
  DECLARE _category VARCHAR(40);
  DECLARE _src_db   VARCHAR(255);
  DECLARE _des_db   VARCHAR(255);
 
  
  SELECT DATABASE()  INTO _src_db;
  SELECT db_name from yp.entity WHERE id=_des_entity_id INTO _des_db;

  
    SELECT ',' INTO @dlm;
    SELECT _src_ids INTO @lst;
    DROP TABLE IF EXISTS _src_lsttbl; 
    CREATE TEMPORARY TABLE _src_lsttbl(`id` varchar(16) DEFAULT NULL); 
    SELECT  LENGTH(@lst) - LENGTH(REPLACE(@lst, @dlm, '')) into @lmt;
    SELECT @lmt+1 into @lmt;
    
    INSERT INTO _src_lsttbl
    SELECT
      SUBSTRING_INDEX(SUBSTRING_INDEX(mytbl.id, @dlm, cnt.n), @dlm, -1) id
    FROM
      (
        SELECT (ons + 10*tns +100*hrds) +1 n FROM 
        (SELECT 0 ons UNION SELECT 1  UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a,
        (SELECT 0 tns UNION SELECT 1  UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b,
            (SELECT 0 hrds UNION SELECT 1  UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) c
        WHERE (ons + 10*tns +100*hrds +1)<=@lmt
        ) cnt 
    INNER JOIN (SELECT @lst as id) mytbl ON CHAR_LENGTH(mytbl.id)-CHAR_LENGTH(REPLACE(mytbl.id, @dlm, ''))>=cnt.n-1;
  
  
  
    SELECT ',' INTO @dlm;
    SELECT _dest_pids INTO @lst;
    DROP TABLE IF EXISTS _dest_lsttbl; 
    CREATE TEMPORARY TABLE _dest_lsttbl(`id` varchar(16) DEFAULT NULL); 
    SELECT  LENGTH(@lst) - LENGTH(REPLACE(@lst, @dlm, '')) into @lmt;
    SELECT @lmt+1 into @lmt;
    
    INSERT INTO _dest_lsttbl
    SELECT
      SUBSTRING_INDEX(SUBSTRING_INDEX(mytbl.id, @dlm, cnt.n), @dlm, -1) id
    FROM
      (
        SELECT (ons + 10*tns +100*hrds) +1 n FROM 
        (SELECT 0 ons UNION SELECT 1  UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a,
        (SELECT 0 tns UNION SELECT 1  UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b,
            (SELECT 0 hrds UNION SELECT 1  UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) c
        WHERE (ons + 10*tns +100*hrds +1)<=@lmt
        ) cnt 
    INNER JOIN (SELECT @lst as id) mytbl ON CHAR_LENGTH(mytbl.id)-CHAR_LENGTH(REPLACE(mytbl.id, @dlm, ''))>=cnt.n-1;
  


    SET @sql = CONCAT(
    '   SELECT 
          s.id source_id,
          s.category ,
          s.user_filename name,
          dp.id dest_id,
          dp.user_filename availablein

        FROM ',_src_db,' .media s
            INNER JOIN ',_des_db,'.media d ON d.user_filename= s.user_filename
            AND s.category = d.category
            INNER JOIN _dest_lsttbl dl on d.parent_id = dl.id
            INNER JOIN _src_lsttbl sl on sl.id = s.id
            INNER JOIN ',_des_db,'.media dp on dp.id=dl.id
            ');
        
    PREPARE stmt FROM @sql ;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `mfs_root_is_exist` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_root_is_exist`(
  IN _src_id VARCHAR(16),
  IN _dest_pid VARCHAR(16),
  IN _des_entity_id VARCHAR(16)
  )
BEGIN
  DECLARE _category VARCHAR(40);
  DECLARE _src_db   VARCHAR(255);
  DECLARE _des_db   VARCHAR(255);

  SELECT DATABASE()  INTO _src_db;
  SELECT db_name from yp.entity WHERE id=_des_entity_id INTO _des_db;

    SET @sql = CONCAT(
    ' SELECT 
          CASE 
              WHEN source.category in ("folder") THEN  2 
              ELSE 1 END status, source.id as nid, destination.id as dest_id
        FROM ',_src_db,' .media source
            INNER JOIN ',_des_db,'.media destination ON destination.user_filename= source.user_filename
            AND source.category = destination.category AND destination.status  = "active"
        WHERE 
          (source.id =''',_src_id,''') AND
          destination.parent_id=''',_dest_pid,'''');
    PREPARE stmt FROM @sql ;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `mfs_search` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_search`(
  IN _pattern VARCHAR(84),
  IN _cat VARCHAR(84),
  IN _page TINYINT(4)
)
BEGIN

  DECLARE _range bigint;
  DECLARE _offset bigint;
  CALL pageToLimits(_page, _offset, _range);

  SELECT   
    media.id   as nid,
    origin_id  AS origin_id,
    @entity_id AS oid,
    extension as ext,
    media.category as filetype,
    user_filename as filename,
    firstname,
    lastname,
    caption,
    filesize,
    upload_time as mtime,
    download_count as views,
    MATCH(`caption`,`user_filename`,`file_path`,`metadata`)
      against(_pattern IN NATURAL LANGUAGE MODE WITH QUERY EXPANSION)
    + IF(MATCH(`caption`,`user_filename`,`file_path`,`metadata`)
      against(concat(_pattern, '*') IN BOOLEAN MODE), 30, 0)
    + IF(user_filename = _pattern, 100, 0)
    + IF(user_filename LIKE concat("%", _pattern, "%"), 27, 0) AS score
    FROM media INNER JOIN yp.drumate ON origin_id=drumate.id HAVING  score > 25 
    AND media.category=_cat
    ORDER BY score DESC, mtime ASC LIMIT _offset, _range;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `mfs_search_names` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_search_names`(
  IN _uid VARCHAR(16) CHARACTER SET ascii,
  IN _scope_nid VARCHAR(16) CHARACTER SET ascii,
  IN _query VARCHAR(128),
  IN _limit TINYINT UNSIGNED
)
BEGIN
  DECLARE _principal VARCHAR(16) CHARACTER SET ascii;
  DECLARE _hub_id VARCHAR(16) CHARACTER SET ascii DEFAULT NULL;
  DECLARE _area VARCHAR(30) DEFAULT NULL;
  DECLARE _needle VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
  DECLARE _result_limit TINYINT UNSIGNED DEFAULT 6;
  DECLARE _now INT UNSIGNED;

  DECLARE _global_permission TINYINT UNSIGNED DEFAULT 0;
  DECLARE _global_expiry INT DEFAULT 0;
  DECLARE _public_permission TINYINT UNSIGNED DEFAULT 0;
  DECLARE _public_expiry INT DEFAULT 0;
  DECLARE _scope_principal_permission TINYINT UNSIGNED DEFAULT 0;
  DECLARE _scope_principal_expiry INT DEFAULT 0;
  DECLARE _scope_principal_blocked TINYINT UNSIGNED DEFAULT 0;
  DECLARE _scope_public_permission TINYINT UNSIGNED DEFAULT 0;
  DECLARE _scope_public_expiry INT DEFAULT 0;
  DECLARE _scope_public_blocked TINYINT UNSIGNED DEFAULT 0;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS _mfs_search_frontier;
    DROP TEMPORARY TABLE IF EXISTS _mfs_search_tree;
    DROP TEMPORARY TABLE IF EXISTS _mfs_search_ancestors;
    DROP TEMPORARY TABLE IF EXISTS _mfs_search_direct_grant;
    RESIGNAL;
  END;

  IF _query IS NULL OR CHAR_LENGTH(_query) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SEARCH_NAMES_QUERY_INVALID';
  END IF;

  SET _principal = IF(_uid IN ('*', 'ffffffffffffffff', 'nobody'), '*', _uid);
  SET _needle = LCASE(CONVERT(_query USING utf8mb4));
  SET _result_limit = LEAST(GREATEST(IFNULL(_limit, 6), 1), 6);
  SET _now = UNIX_TIMESTAMP();

  SELECT e.id, e.area
    INTO _hub_id, _area
    FROM yp.entity e
    WHERE e.db_name = DATABASE()
    LIMIT 1;

  IF _hub_id IS NULL OR _principal IS NULL OR _scope_nid IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SEARCH_NAMES_SCOPE_INVALID';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM media m
    WHERE m.id = _scope_nid
      AND m.category = 'folder'
      AND m.isalink = 0
      AND m.status NOT IN ('hidden', 'deleted')
      AND m.file_path NOT REGEXP '^/__(chat|trash|upload)__'
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SEARCH_NAMES_SCOPE_INVALID';
  END IF;

  IF _principal <> '*' THEN
    SELECT
      IFNULL(p.permission, 0),
      IFNULL(p.expiry_time, 0)
    INTO
      _global_permission,
      _global_expiry
    FROM (SELECT 1 AS seed) s
    LEFT JOIN permission p
      ON p.resource_id = '*'
      AND p.entity_id = _principal
      AND p.permission <> 0;
  END IF;

  SELECT p.permission, p.expiry_time
    INTO _public_permission, _public_expiry
    FROM permission p
    WHERE p.resource_id = '*'
      AND p.entity_id IN ('*', 'ffffffffffffffff', 'nobody')
      AND p.permission <> 0
    ORDER BY
      p.permission DESC,
      CASE p.entity_id
        WHEN '*' THEN 0
        WHEN 'ffffffffffffffff' THEN 1
        ELSE 2
      END ASC,
      p.sys_id ASC
    LIMIT 1;

  DROP TEMPORARY TABLE IF EXISTS _mfs_search_direct_grant;
  CREATE TEMPORARY TABLE _mfs_search_direct_grant (
    resource_id VARCHAR(16) CHARACTER SET ascii NOT NULL,
    permission TINYINT UNSIGNED NOT NULL,
    expiry_time INT NOT NULL,
    assign_via VARCHAR(32) DEFAULT NULL,
    PRIMARY KEY (resource_id)
  ) ENGINE = InnoDB;

  INSERT INTO _mfs_search_direct_grant (
    resource_id,
    permission,
    expiry_time,
    assign_via
  )
  SELECT
    ranked.resource_id,
    ranked.permission,
    ranked.expiry_time,
    ranked.assign_via
  FROM (
    SELECT
      p.resource_id,
      p.permission,
      p.expiry_time,
      p.assign_via,
      ROW_NUMBER() OVER (
        PARTITION BY p.resource_id
        ORDER BY
          p.permission DESC,
          CASE
            WHEN p.entity_id = _principal THEN 0
            WHEN p.entity_id = '*' THEN 1
            WHEN p.entity_id = 'ffffffffffffffff' THEN 2
            ELSE 3
          END ASC,
          p.sys_id ASC
      ) AS grant_rank
    FROM permission p
    WHERE p.resource_id <> '*'
      AND p.entity_id IN (
        _principal,
        '*',
        'ffffffffffffffff',
        'nobody'
      )
      AND p.permission <> 0
  ) ranked
  WHERE ranked.grant_rank = 1;

  DROP TEMPORARY TABLE IF EXISTS _mfs_search_ancestors;
  CREATE TEMPORARY TABLE _mfs_search_ancestors (
    nid VARCHAR(16) CHARACTER SET ascii NOT NULL,
    parent_id VARCHAR(16) CHARACTER SET ascii DEFAULT NULL,
    depth SMALLINT UNSIGNED NOT NULL,
    visited VARCHAR(18000) CHARACTER SET ascii NOT NULL,
    cycle_found TINYINT UNSIGNED NOT NULL DEFAULT 0,
    KEY nid (nid),
    KEY depth (depth)
  ) ENGINE = InnoDB;

  INSERT INTO _mfs_search_ancestors (
    nid,
    parent_id,
    depth,
    visited,
    cycle_found
  )
  WITH RECURSIVE scope_ancestors AS (
    SELECT
      m.id AS nid,
      m.parent_id,
      CAST(0 AS UNSIGNED) AS depth,
      CAST(
        CONVERT(CONCAT('|', m.id, '|') USING ascii)
        AS CHAR(18000)
      ) AS visited,
      0 AS cycle_found
    FROM media m
    WHERE m.id = _scope_nid

    UNION ALL

    SELECT
      m.id AS nid,
      m.parent_id,
      a.depth + 1 AS depth,
      LEFT(CONCAT(a.visited, m.id, '|'), 18000) AS visited,
      IF(LOCATE(CONCAT('|', m.id, '|'), a.visited) > 0, 1, 0)
        AS cycle_found
    FROM scope_ancestors a
    INNER JOIN media m ON m.id = a.parent_id
    WHERE a.parent_id IS NOT NULL
      AND a.parent_id <> '0'
      AND a.cycle_found = 0
      AND a.depth < 1000
  )
  SELECT
    nid,
    parent_id,
    depth,
    visited,
    cycle_found
  FROM scope_ancestors;

  IF EXISTS (
    SELECT 1 FROM _mfs_search_ancestors WHERE cycle_found = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TREE_CYCLE';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM _mfs_search_ancestors a
    INNER JOIN media m ON m.id = a.parent_id
    WHERE a.depth = 1000
      AND a.parent_id IS NOT NULL
      AND a.parent_id <> '0'
      AND LOCATE(CONCAT('|', m.id, '|'), a.visited) > 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TREE_CYCLE';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM _mfs_search_ancestors a
    INNER JOIN media m ON m.id = a.parent_id
    WHERE a.depth = 1000
      AND a.parent_id IS NOT NULL
      AND a.parent_id <> '0'
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TREE_DEPTH_EXCEEDED';
  END IF;

  IF _principal <> '*' THEN
    SELECT
      IF(p.assign_via IN ('root', 'no_traversal'), 0, p.permission),
      IF(p.assign_via IN ('root', 'no_traversal'), 0, p.expiry_time),
      IF(p.assign_via IN ('root', 'no_traversal'), 1, 0)
    INTO
      _scope_principal_permission,
      _scope_principal_expiry,
      _scope_principal_blocked
    FROM _mfs_search_ancestors a
    INNER JOIN permission p
      ON p.resource_id = a.nid
      AND p.entity_id = _principal
    WHERE a.depth > 0
      AND (
        p.permission <> 0
        OR p.assign_via IN ('root', 'no_traversal')
      )
    ORDER BY a.depth ASC
    LIMIT 1;
  END IF;

  SELECT
    IF(p.assign_via IN ('root', 'no_traversal'), 0, p.permission),
    IF(p.assign_via IN ('root', 'no_traversal'), 0, p.expiry_time),
    IF(p.assign_via IN ('root', 'no_traversal'), 1, 0)
  INTO
    _scope_public_permission,
    _scope_public_expiry,
    _scope_public_blocked
  FROM _mfs_search_ancestors a
  INNER JOIN permission p
    ON p.resource_id = a.nid
    AND p.entity_id = '*'
  WHERE a.depth > 0
    AND (
      p.permission <> 0
      OR p.assign_via IN ('root', 'no_traversal')
    )
  ORDER BY a.depth ASC
  LIMIT 1;

  DROP TEMPORARY TABLE IF EXISTS _mfs_search_tree;
  CREATE TEMPORARY TABLE _mfs_search_tree (
    nid VARCHAR(16) CHARACTER SET ascii NOT NULL,
    parent_id VARCHAR(16) CHARACTER SET ascii DEFAULT NULL,
    filename VARCHAR(128) DEFAULT NULL,
    extension VARCHAR(100) CHARACTER SET ascii DEFAULT NULL,
    mimetype VARCHAR(100) NOT NULL,
    category VARCHAR(16) NOT NULL,
    isalink TINYINT UNSIGNED NOT NULL,
    mention_path VARCHAR(4096) CHARACTER SET utf8mb4 NOT NULL,
    effective_permission TINYINT UNSIGNED NOT NULL,
    effective_expiry INT NOT NULL,
    principal_lineage_permission TINYINT UNSIGNED NOT NULL,
    principal_lineage_expiry INT NOT NULL,
    principal_lineage_blocked TINYINT UNSIGNED NOT NULL,
    public_lineage_permission TINYINT UNSIGNED NOT NULL,
    public_lineage_expiry INT NOT NULL,
    public_lineage_blocked TINYINT UNSIGNED NOT NULL,
    depth SMALLINT UNSIGNED NOT NULL,
    visited VARCHAR(18000) CHARACTER SET ascii NOT NULL,
    cycle_found TINYINT UNSIGNED NOT NULL DEFAULT 0,
    path_too_long TINYINT UNSIGNED NOT NULL DEFAULT 0,
    KEY nid (nid),
    KEY depth (depth)
  ) ENGINE = InnoDB;

  INSERT INTO _mfs_search_tree (
    nid,
    parent_id,
    filename,
    extension,
    mimetype,
    category,
    isalink,
    mention_path,
    effective_permission,
    effective_expiry,
    principal_lineage_permission,
    principal_lineage_expiry,
    principal_lineage_blocked,
    public_lineage_permission,
    public_lineage_expiry,
    public_lineage_blocked,
    depth,
    visited,
    cycle_found,
    path_too_long
  )
  WITH RECURSIVE search_tree AS (
    SELECT
      m.id AS nid,
      m.parent_id,
      m.user_filename AS filename,
      m.extension,
      m.mimetype,
      m.category,
      m.isalink,
      CAST(CONVERT('' USING utf8mb4) AS CHAR(4096)) AS mention_path,
      CASE
        WHEN _global_permission <> 0 THEN _global_permission
        WHEN dg.permission IS NOT NULL THEN dg.permission
        WHEN _scope_principal_permission >= _scope_public_permission
          AND _scope_principal_permission <> 0
          THEN _scope_principal_permission
        WHEN _scope_public_permission <> 0 THEN _scope_public_permission
        ELSE _public_permission
      END AS effective_permission,
      CASE
        WHEN _global_permission <> 0 THEN _global_expiry
        WHEN dg.permission IS NOT NULL THEN dg.expiry_time
        WHEN _scope_principal_permission >= _scope_public_permission
          AND _scope_principal_permission <> 0
          THEN _scope_principal_expiry
        WHEN _scope_public_permission <> 0 THEN _scope_public_expiry
        ELSE _public_expiry
      END AS effective_expiry,
      CASE
        WHEN pp.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pp.permission, 0) <> 0 THEN pp.permission
        ELSE _scope_principal_permission
      END AS principal_lineage_permission,
      CASE
        WHEN pp.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pp.permission, 0) <> 0 THEN pp.expiry_time
        ELSE _scope_principal_expiry
      END AS principal_lineage_expiry,
      CASE
        WHEN pp.assign_via IN ('root', 'no_traversal') THEN 1
        WHEN IFNULL(pp.permission, 0) <> 0 THEN 0
        ELSE _scope_principal_blocked
      END AS principal_lineage_blocked,
      CASE
        WHEN pw.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pw.permission, 0) <> 0 THEN pw.permission
        ELSE _scope_public_permission
      END AS public_lineage_permission,
      CASE
        WHEN pw.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pw.permission, 0) <> 0 THEN pw.expiry_time
        ELSE _scope_public_expiry
      END AS public_lineage_expiry,
      CASE
        WHEN pw.assign_via IN ('root', 'no_traversal') THEN 1
        WHEN IFNULL(pw.permission, 0) <> 0 THEN 0
        ELSE _scope_public_blocked
      END AS public_lineage_blocked,
      CAST(0 AS UNSIGNED) AS depth,
      CAST(
        CONVERT(CONCAT('|', m.id, '|') USING ascii)
        AS CHAR(18000)
      ) AS visited,
      0 AS cycle_found,
      0 AS path_too_long
    FROM media m
    LEFT JOIN _mfs_search_direct_grant dg ON dg.resource_id = m.id
    LEFT JOIN permission pp
      ON pp.resource_id = m.id
      AND pp.entity_id = _principal
      AND _principal <> '*'
    LEFT JOIN permission pw
      ON pw.resource_id = m.id
      AND pw.entity_id = '*'
    WHERE m.id = _scope_nid
      AND m.category = 'folder'
      AND m.isalink = 0
      AND m.status NOT IN ('hidden', 'deleted')
      AND m.file_path NOT REGEXP '^/__(chat|trash|upload)__'
      AND (
        CASE
          WHEN _global_permission <> 0 THEN _global_permission
          WHEN dg.permission IS NOT NULL THEN dg.permission
          WHEN _scope_principal_permission >= _scope_public_permission
            AND _scope_principal_permission <> 0
            THEN _scope_principal_permission
          WHEN _scope_public_permission <> 0 THEN _scope_public_permission
          ELSE _public_permission
        END & 2
      ) = 2
      AND (
        CASE
          WHEN _global_permission <> 0 THEN _global_expiry
          WHEN dg.permission IS NOT NULL THEN dg.expiry_time
          WHEN _scope_principal_permission >= _scope_public_permission
            AND _scope_principal_permission <> 0
            THEN _scope_principal_expiry
          WHEN _scope_public_permission <> 0 THEN _scope_public_expiry
          ELSE _public_expiry
        END = 0
        OR
        CASE
          WHEN _global_permission <> 0 THEN _global_expiry
          WHEN dg.permission IS NOT NULL THEN dg.expiry_time
          WHEN _scope_principal_permission >= _scope_public_permission
            AND _scope_principal_permission <> 0
            THEN _scope_principal_expiry
          WHEN _scope_public_permission <> 0 THEN _scope_public_expiry
          ELSE _public_expiry
        END > _now
      )

    UNION ALL

    SELECT
      m.id AS nid,
      m.parent_id,
      m.user_filename AS filename,
      m.extension,
      m.mimetype,
      m.category,
      m.isalink,
      LEFT(
        IF(
          t.depth = 0,
          IFNULL(m.user_filename, ''),
          CONCAT(t.mention_path, '/', IFNULL(m.user_filename, ''))
        ),
        4096
      ) AS mention_path,
      CASE
        WHEN _global_permission <> 0 THEN _global_permission
        WHEN dg.permission IS NOT NULL THEN dg.permission
        WHEN t.principal_lineage_permission >= t.public_lineage_permission
          AND t.principal_lineage_permission <> 0
          THEN t.principal_lineage_permission
        WHEN t.public_lineage_permission <> 0
          THEN t.public_lineage_permission
        ELSE _public_permission
      END AS effective_permission,
      CASE
        WHEN _global_permission <> 0 THEN _global_expiry
        WHEN dg.permission IS NOT NULL THEN dg.expiry_time
        WHEN t.principal_lineage_permission >= t.public_lineage_permission
          AND t.principal_lineage_permission <> 0
          THEN t.principal_lineage_expiry
        WHEN t.public_lineage_permission <> 0
          THEN t.public_lineage_expiry
        ELSE _public_expiry
      END AS effective_expiry,
      CASE
        WHEN pp.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pp.permission, 0) <> 0 THEN pp.permission
        ELSE t.principal_lineage_permission
      END AS principal_lineage_permission,
      CASE
        WHEN pp.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pp.permission, 0) <> 0 THEN pp.expiry_time
        ELSE t.principal_lineage_expiry
      END AS principal_lineage_expiry,
      CASE
        WHEN pp.assign_via IN ('root', 'no_traversal') THEN 1
        WHEN IFNULL(pp.permission, 0) <> 0 THEN 0
        ELSE t.principal_lineage_blocked
      END AS principal_lineage_blocked,
      CASE
        WHEN pw.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pw.permission, 0) <> 0 THEN pw.permission
        ELSE t.public_lineage_permission
      END AS public_lineage_permission,
      CASE
        WHEN pw.assign_via IN ('root', 'no_traversal') THEN 0
        WHEN IFNULL(pw.permission, 0) <> 0 THEN pw.expiry_time
        ELSE t.public_lineage_expiry
      END AS public_lineage_expiry,
      CASE
        WHEN pw.assign_via IN ('root', 'no_traversal') THEN 1
        WHEN IFNULL(pw.permission, 0) <> 0 THEN 0
        ELSE t.public_lineage_blocked
      END AS public_lineage_blocked,
      t.depth + 1 AS depth,
      LEFT(CONCAT(t.visited, m.id, '|'), 18000) AS visited,
      IF(LOCATE(CONCAT('|', m.id, '|'), t.visited) > 0, 1, 0)
        AS cycle_found,
      IF(
        CHAR_LENGTH(
          IF(
            t.depth = 0,
            IFNULL(m.user_filename, ''),
            CONCAT(t.mention_path, '/', IFNULL(m.user_filename, ''))
          )
        ) > 4096,
        1,
        0
      ) AS path_too_long
    FROM search_tree t
    INNER JOIN media m ON m.parent_id = t.nid
    LEFT JOIN _mfs_search_direct_grant dg ON dg.resource_id = m.id
    LEFT JOIN permission pp
      ON pp.resource_id = m.id
      AND pp.entity_id = _principal
      AND _principal <> '*'
    LEFT JOIN permission pw
      ON pw.resource_id = m.id
      AND pw.entity_id = '*'
    WHERE t.cycle_found = 0
      AND t.path_too_long = 0
      AND t.depth < 1000
      AND t.category = 'folder'
      AND t.isalink = 0
      AND m.category NOT IN ('hub', 'root')
      AND m.status NOT IN ('hidden', 'deleted')
      AND m.file_path NOT REGEXP '^/__(chat|trash|upload)__'
      AND (
        CASE
          WHEN _global_permission <> 0 THEN _global_permission
          WHEN dg.permission IS NOT NULL THEN dg.permission
          WHEN t.principal_lineage_permission >= t.public_lineage_permission
            AND t.principal_lineage_permission <> 0
            THEN t.principal_lineage_permission
          WHEN t.public_lineage_permission <> 0
            THEN t.public_lineage_permission
          ELSE _public_permission
        END & 2
      ) = 2
      AND (
        CASE
          WHEN _global_permission <> 0 THEN _global_expiry
          WHEN dg.permission IS NOT NULL THEN dg.expiry_time
          WHEN t.principal_lineage_permission >= t.public_lineage_permission
            AND t.principal_lineage_permission <> 0
            THEN t.principal_lineage_expiry
          WHEN t.public_lineage_permission <> 0
            THEN t.public_lineage_expiry
          ELSE _public_expiry
        END = 0
        OR
        CASE
          WHEN _global_permission <> 0 THEN _global_expiry
          WHEN dg.permission IS NOT NULL THEN dg.expiry_time
          WHEN t.principal_lineage_permission >= t.public_lineage_permission
            AND t.principal_lineage_permission <> 0
            THEN t.principal_lineage_expiry
          WHEN t.public_lineage_permission <> 0
            THEN t.public_lineage_expiry
          ELSE _public_expiry
        END > _now
      )
  )
  SELECT
    nid,
    parent_id,
    filename,
    extension,
    mimetype,
    category,
    isalink,
    mention_path,
    effective_permission,
    effective_expiry,
    principal_lineage_permission,
    principal_lineage_expiry,
    principal_lineage_blocked,
    public_lineage_permission,
    public_lineage_expiry,
    public_lineage_blocked,
    depth,
    visited,
    cycle_found,
    path_too_long
  FROM search_tree;

  IF NOT EXISTS (
    SELECT 1 FROM _mfs_search_tree WHERE depth = 0
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SEARCH_NAMES_SCOPE_INVALID';
  END IF;

  IF EXISTS (
    SELECT 1 FROM _mfs_search_tree WHERE cycle_found = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TREE_CYCLE';
  END IF;

  DROP TEMPORARY TABLE IF EXISTS _mfs_search_frontier;
  CREATE TEMPORARY TABLE _mfs_search_frontier (
    cycle_found TINYINT UNSIGNED NOT NULL DEFAULT 0
  ) ENGINE = InnoDB;

  INSERT INTO _mfs_search_frontier (cycle_found)
  SELECT
    IF(LOCATE(CONCAT('|', m.id, '|'), t.visited) > 0, 1, 0)
  FROM _mfs_search_tree t
  INNER JOIN media m ON m.parent_id = t.nid
  LEFT JOIN _mfs_search_direct_grant dg ON dg.resource_id = m.id
  WHERE t.depth = 1000
    AND t.cycle_found = 0
    AND t.path_too_long = 0
    AND t.category = 'folder'
    AND t.isalink = 0
    AND m.category NOT IN ('hub', 'root')
    AND m.status NOT IN ('hidden', 'deleted')
    AND m.file_path NOT REGEXP '^/__(chat|trash|upload)__'
    AND (
      CASE
        WHEN _global_permission <> 0 THEN _global_permission
        WHEN dg.permission IS NOT NULL THEN dg.permission
        WHEN t.principal_lineage_permission >= t.public_lineage_permission
          AND t.principal_lineage_permission <> 0
          THEN t.principal_lineage_permission
        WHEN t.public_lineage_permission <> 0
          THEN t.public_lineage_permission
        ELSE _public_permission
      END & 2
    ) = 2
    AND (
      CASE
        WHEN _global_permission <> 0 THEN _global_expiry
        WHEN dg.permission IS NOT NULL THEN dg.expiry_time
        WHEN t.principal_lineage_permission >= t.public_lineage_permission
          AND t.principal_lineage_permission <> 0
          THEN t.principal_lineage_expiry
        WHEN t.public_lineage_permission <> 0
          THEN t.public_lineage_expiry
        ELSE _public_expiry
      END = 0
      OR
      CASE
        WHEN _global_permission <> 0 THEN _global_expiry
        WHEN dg.permission IS NOT NULL THEN dg.expiry_time
        WHEN t.principal_lineage_permission >= t.public_lineage_permission
          AND t.principal_lineage_permission <> 0
          THEN t.principal_lineage_expiry
        WHEN t.public_lineage_permission <> 0
          THEN t.public_lineage_expiry
        ELSE _public_expiry
      END > _now
    );

  IF EXISTS (
    SELECT 1 FROM _mfs_search_frontier WHERE cycle_found = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TREE_CYCLE';
  END IF;

  IF EXISTS (
    SELECT 1 FROM _mfs_search_frontier
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TREE_DEPTH_EXCEEDED';
  END IF;

  IF EXISTS (
    SELECT 1 FROM _mfs_search_tree WHERE path_too_long = 1
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MENTION_PATH_TOO_LONG';
  END IF;

  SELECT
    t.nid,
    _hub_id AS hub_id,
    t.parent_id,
    t.filename,
    t.category AS filetype,
    t.extension AS ext,
    t.mimetype,
    fc.capability,
    _area AS area,
    t.isalink,
    t.mention_path
  FROM _mfs_search_tree t
  LEFT JOIN yp.filecap fc ON fc.extension = t.extension
  WHERE t.depth > 0
    AND (t.effective_permission & 2) = 2
    AND (t.effective_expiry = 0 OR t.effective_expiry > _now)
    AND (
      LOCATE(
        _needle,
        LCASE(CONVERT(IFNULL(t.filename, '') USING utf8mb4))
          COLLATE utf8mb4_bin
      ) > 0
      OR LOCATE(
        _needle,
        LCASE(CONVERT(t.mention_path USING utf8mb4))
          COLLATE utf8mb4_bin
      ) > 0
    )
  ORDER BY
    CASE
      WHEN LCASE(CONVERT(IFNULL(t.filename, '') USING utf8mb4))
        COLLATE utf8mb4_bin = _needle THEN 0
      WHEN LOCATE(
        _needle,
        LCASE(CONVERT(IFNULL(t.filename, '') USING utf8mb4))
          COLLATE utf8mb4_bin
      ) = 1 THEN 1
      WHEN LOCATE(
        _needle,
        LCASE(CONVERT(IFNULL(t.filename, '') USING utf8mb4))
          COLLATE utf8mb4_bin
      ) > 0 THEN 2
      ELSE 3
    END ASC,
    LCASE(CONVERT(IFNULL(t.filename, '') USING utf8mb4))
      COLLATE utf8mb4_bin ASC,
    LCASE(CONVERT(t.mention_path USING utf8mb4))
      COLLATE utf8mb4_bin ASC,
    t.nid ASC
  LIMIT _result_limit;

  DROP TEMPORARY TABLE IF EXISTS _mfs_search_frontier;
  DROP TEMPORARY TABLE IF EXISTS _mfs_search_tree;
  DROP TEMPORARY TABLE IF EXISTS _mfs_search_ancestors;
  DROP TEMPORARY TABLE IF EXISTS _mfs_search_direct_grant;
END ;;
DELIMITER ;
