CREATE PROCEDURE `mfs_set_poster`(
  IN _id VARBINARY(16)
)
BEGIN
  
  
  
  UPDATE media SET `metadata` =
    JSON_SET( IF(JSON_VALID(metadata), metadata, '{}'), '$.poster', 1)
  WHERE id = _id;
END ;;
