CREATE PROCEDURE `page_delete_by_lang`(
   IN _locale       VARCHAR(100)
)
BEGIN
  DELETE FROM page_history WHERE lang=_locale;
  DELETE page FROM page WHERE id NOT IN (SELECT master_id FROM page_history);
END ;;
