   IN _key VARCHAR(512)
)
BEGIN
  SELECT page.id, active, hashtag, `type`, editor, status, firstname, lastname ctime, mtime, version
    FROM page LEFT JOIN yp.drumate ON author_id=drumate.id WHERE page.id = _key OR hashtag= _key;
END ;;
