CREATE PROCEDURE `permission_get_direct`(
  IN _rid VARCHAR(16),
  IN _eid VARCHAR(16)
)
BEGIN
  
  
  
  
  
  
  SELECT permission, message, assign_via
    FROM permission WHERE resource_id=_rid AND entity_id=_eid LIMIT 1;
END ;;
