CREATE PROCEDURE `poll_get`(
  IN _key VARCHAR(80)
)
BEGIN

  SELECT
    poll.id as id,
    author_id,
    ident,
    `name`,
    ctime,
    referer,
    ip,
    concat(firstname, ' ', lastname) as author
  FROM poll left join yp.drumate ON drumate.id=author_id WHERE id = _key OR ident = _key;

END ;;
