CREATE PROCEDURE `rmdir`(
  IN mid VARBINARY(16)
)
BEGIN
  DECLARE dirname VARCHAR(255);
  SELECT file_path FROM media  WHERE id=mid INTO dirname;
  DELETE FROM media WHERE file_path LIKE CONCAT(dirname, '/%');
  DELETE FROM media WHERE id=mid;
END ;;
