CREATE PROCEDURE `room_invite`(
  IN _id VARCHAR(16), 
  IN _user_id VARCHAR(16), 
  IN _socket_id VARCHAR(32),
  IN _type VARCHAR(32)
)
BEGIN
  INSERT INTO room (
      id, 
      user_id, 
      socket_id, 
      ctime, 
      `type`,
      `role`
    )
    VALUES(
      _id, 
      _user_id, 
      _socket_id, 
      UNIX_TIMESTAMP(), 
      _type, 
      'attendee'
    )ON DUPLICATE KEY UPDATE socket_id=_socket_id, `type`=_type;

  CALL permission_grant(_id, _user_id, 24, 3, 'no_traversal', _socket_id);
END ;;
DELIMITER ;
