CREATE PROCEDURE `test_limit`(
  IN _page int
)
BEGIN
  DECLARE total bigint;
  DECLARE _offset bigint;
  DECLARE perpage INT DEFAULT 20;
  SELECT count(*) FROM media into total;

  SELECT FLOOR(total/perpage)*_page INTO _offset;

END ;;
DELIMITER ;
